// ─── Hermes-safe base64 decode ────────────────────────────────────────────────
const b64decode = (str: string): string => {
  const chars =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  let output = '';
  const s = str.replace(/[^A-Za-z0-9+/=]/g, '');
  for (let i = 0; i < s.length; ) {
    const e1 = chars.indexOf(s[i++]);
    const e2 = chars.indexOf(s[i++]);
    const e3 = chars.indexOf(s[i++]);
    const e4 = chars.indexOf(s[i++]);
    const c1 = (e1 << 2) | (e2 >> 4);
    const c2 = ((e2 & 15) << 4) | (e3 >> 2);
    const c3 = ((e3 & 3) << 6) | e4;
    output += String.fromCharCode(c1);
    if (e3 !== 64) output += String.fromCharCode(c2);
    if (e4 !== 64) output += String.fromCharCode(c3);
  }
  return output;
};

// ─── Keychain helpers ─────────────────────────────────────────────────────────
const getSavedToken = async (): Promise<string | null> => {
  try {
    const creds = await Keychain.getGenericPassword();
    if (!creds?.password) return null;
    return JSON.parse(creds.password)?.token ?? null;
  } catch {
    return null;
  }
};

const getSavedUserId = async (): Promise<number | null> => {
  try {
    const creds = await Keychain.getGenericPassword();
    if (!creds?.password) return null;
    const parsed = JSON.parse(creds.password);
    if (parsed?.userId) return Number(parsed.userId);
    if (parsed?.token) {
      const parts = parsed.token.split('.');
      if (parts.length === 3) {
        try {
          const base64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
          // Same fix as authApi.ts — correct padding is (4 - len%4) % 4
          // '=' chars; the old formula produced 0 padding for the two most
          // common lengths, corrupting the decoded JSON with a trailing byte.
          const padded = base64 + '='.repeat((4 - (base64.length % 4)) % 4);
          const payload = JSON.parse(b64decode(padded));
          const id = payload?.data?.user?.id;
          if (id) return Number(id);
        } catch {}
      }
    }
    return null;
  } catch {
    return null;
  }
};

// ─── xProfile field lookup by name (not by ID — IDs are unreliable) ──────────
const getXProfileByName = (data: any, fieldName: string): string => {
  const groups = data?.xprofile?.groups;
  if (!groups || typeof groups !== 'object') return '';
  for (const gk of Object.keys(groups)) {
    const fields = groups[gk]?.fields;
    if (!fields || typeof fields !== 'object') continue;
    for (const fk of Object.keys(fields)) {
      if (fields[fk]?.name === fieldName) return fields[fk]?.value?.raw || '';
    }
  }
  return '';
};

// ─── xProfile field lookup by CONFIRMED field ID ─────────────────────────────
// Job Title (1097) and Country (1099) IDs are confirmed stable across the
// codebase (see MemberProfileScreen/feedApi). Name-only lookup was silently
// returning '' whenever the field's stored name didn't match the exact
// string "Job Title", which is why the drawer's title could drift out of
// sync with MemberProfileScreen (which already falls back to the ID). Try
// the ID first, then fall back to the name match for safety.
const getXProfileById = (data: any, fieldId: number): string => {
  const groups = data?.xprofile?.groups;
  if (!groups || typeof groups !== 'object') return '';
  for (const gk of Object.keys(groups)) {
    const fields = groups[gk]?.fields;
    if (!fields || typeof fields !== 'object') continue;
    const field = fields[String(fieldId)];
    if (field?.value?.raw) return field.value.raw.trim();
  }
  return '';
};

